//! 🪡️ Native Part21 subtree input and collection movement advance through original funded owners.
use super::*;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind};
use semio_framework_value::retained_clone::{RetainedCloneSource,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedCloneClose,retained_clone_grant_admits};
use semio_framework_value::native_decoding::owned::NativeReceivingOriginal;
use std::mem::size_of;
type Input=RetainedCloneSource<DslValue>;
type Receiving=NativeReceivingOriginal<DslValue,V>;
#[derive(Clone,Copy)]enum Target{Whole,Items,Payload,Collection(usize)}
#[derive(Clone,Copy)]enum Operation{Set,Insert,Remove,Move(usize)}
#[derive(Clone,Copy)]struct Path{part:usize,argument:usize,children:[usize;128],length:usize,target:Target}
#[derive(Clone,Copy)]enum Phase{Start,Input,Source,Shell,Capture,Birth,Receive,Take,Apply,Allocate,Rebuild,Done}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"Part21 native subtree edit shape or owner is invalid")}
fn parse(event:&SnapshotEditEvent)->Result<(Path,Operation),Fault>{let(path,operation)=match event{SnapshotEditEvent::SetValue{path,..}=>(path,Operation::Set),SnapshotEditEvent::InsertValue{path,..}=>(path,Operation::Insert),SnapshotEditEvent::RemoveValue{path}=>(path,Operation::Remove),SnapshotEditEvent::MoveValue{path,from}=>{let(parent,from)=from.rsplit_once('/').ok_or_else(||err("Part21 move origin is missing"))?;if path.rsplit_once('/').map(|(path,_)|path)!=Some(parent){return Err(err("Part21 move must stay in one native collection"));}(path,Operation::Move(from.parse::<usize>().map_err(|_|err("Invalid Part21 move origin"))?))},_=>return Err(err("Part21 native subtree cannot rename fields"))};let mut fields=path.split('/').skip(1);if fields.next()!=Some("document")||fields.next()!=Some("instances"){return Err(err("Part21 native edit requires an instance path"));}let _row=fields.next().and_then(|value|value.parse::<usize>().ok()).ok_or_else(||err("Invalid Part21 row"))?;if fields.next()!=Some("entities"){return Err(err("Part21 native edit requires a constituent"));}let part=fields.next().and_then(|value|value.parse::<usize>().ok()).ok_or_else(||err("Invalid Part21 constituent"))?;if fields.next()!=Some("arguments"){return Err(err("Part21 native edit requires arguments"));}let argument=fields.next().and_then(|value|value.parse::<usize>().ok()).ok_or_else(||err("Invalid Part21 argument"))?;let mut result=Path{part,argument,children:[0;128],length:0,target:Target::Whole};let mut fields=fields.peekable();while let Some(field)=fields.next(){if field=="value"&&fields.peek().is_none(){result.target=Target::Payload;break;}if field!="values"{return Err(err("Part21 native edit field is not structural"));}let Some(index)=fields.next()else{result.target=Target::Items;break};let index=if index=="-"{usize::MAX}else{index.parse::<usize>().map_err(|_|err("Invalid Part21 child index"))?};if fields.peek().is_none()&&!matches!(operation,Operation::Set){result.target=Target::Collection(index);break;}if result.length==128||index==usize::MAX{return Err(err("Part21 native path exceeds its bound"));}result.children[result.length]=index;result.length+=1;}Ok((result,operation))}
fn target<'a>(instance:&'a mut Part21Instance,path:Path)->Result<&'a mut V,Fault>{let mut value=instance.entities.get_mut(path.part).and_then(|(_,args)|args.get_mut(path.argument)).ok_or_else(||err("Part21 native argument is missing"))?;for index in &path.children[..path.length]{value=match value{V::List(items)|V::Typed{items,..}=>items.get_mut(*index),_=>None}.ok_or_else(||err("Part21 native child is missing"))?;}Ok(value)}
fn items(value:&mut V)->Result<&mut Vec<V>,Fault>{match value{V::List(items)|V::Typed{items,..}=>Ok(items),_=>Err(err("Part21 native collection is missing"))}}
pub(super)struct Part21FieldEdit{path:Option<Path>,operation:Operation,phase:Phase,input:Option<DslValue>,source:Option<Input>,receiving:Option<Receiving>,received:Option<V>,old:Option<V>,collection:Option<Vec<V>>,output:Option<Vec<V>>,retirement:RetainedCloneClose,index:usize,length:usize,closing:bool}
impl Default for Part21FieldEdit{fn default()->Self{Self{path:None,operation:Operation::Set,phase:Phase::Start,input:None,source:None,receiving:None,received:None,old:None,collection:None,output:None,retirement:Default::default(),index:0,length:0,closing:false}}}

impl Part21FieldEdit{
 pub(super)fn supports(event:&SnapshotEditEvent)->bool{let path=match event{SnapshotEditEvent::SetValue{path,..}|SnapshotEditEvent::InsertValue{path,..}|SnapshotEditEvent::RemoveValue{path}|SnapshotEditEvent::MoveValue{path,..}=>path,_=>return false};let mut fields=path.split('/');path.starts_with("/document/instances/")&&fields.nth(6)==Some("arguments")&&fields.next().is_some()}
 pub(super)fn demands(&self,body:usize)->Result<RetirementDemand,ValueError>{let fixed=||RetirementDemand{copy_bytes:2*size_of::<Path>()+3*size_of::<V>()+size_of::<DslValue>(),depth:1,..Default::default()};match self.phase{
 Phase::Source=>{let birth=Input::owned_constructor_demand::<()>();Ok(RetirementDemand{copy_bytes:2*size_of::<Option<Input>>()+size_of::<DslValue>(),capacity_bytes:birth.capacity_bytes,depth:birth.depth,..Default::default()})},
 Phase::Shell=>Ok(Receiving::shell_demand()),Phase::Capture=>self.receiving.as_ref().ok_or_else(invalid)?.original_capture_demand(),Phase::Birth=>self.receiving.as_ref().ok_or_else(invalid)?.receiver_birth_demand(),Phase::Receive=>self.receiving.as_ref().ok_or_else(invalid)?.demands(body),Phase::Take=>self.receiving.as_ref().ok_or_else(invalid)?.take_demand(),
 Phase::Input=>Ok(RetirementDemand{capacity_bytes:2*size_of::<(String,DslValue)>()+32,..fixed()}),Phase::Allocate=>Ok(RetirementDemand{capacity_bytes:self.length.checked_mul(size_of::<V>()).ok_or_else(invalid)?,..fixed()}),_=>Ok(fixed())}}
 pub(super)fn advance(&mut self,instance:&mut Part21Instance,event:&mut SnapshotEditEvent,cx:&mut semio_framework_job::StepContext<'_>)->Result<bool,semio_framework_job::OriginalTurnFailure>{if cx.is_cancelled(){return Err(err("Part21 native subtree receiving cancelled").into());}if cx.should_yield(){return Ok(false);}if matches!(self.phase,Phase::Done){return Ok(true);}let demand=self.demands(64)?;let grant=cx.retained_grant();if !retained_clone_grant_admits(grant,demand){return Ok(false);}let mut progress=RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()};
 match self.phase{
 Phase::Start=>{let(path,operation)=parse(event)?;self.path=Some(path);self.operation=operation;self.phase=if matches!(operation,Operation::Set|Operation::Insert){Phase::Input}else{Phase::Apply};}
 Phase::Input=>{let path=self.path.unwrap();let exemplar=target(instance,path)?;let wrapping=match path.target{Target::Items=>Some(("list","values")),Target::Payload=>Some(match exemplar{V::Str(_)=>("str","value"),V::Enum(_)=>("enum","value"),V::Binary(_)=>("binary","value"),V::Int(_)=>("int","value"),V::Ref(_)=>("ref","value"),V::Real(_)=>("real","value"),_=>return Err(err("Part21 native payload is not scalar").into())}),_=>None};let input=match event{SnapshotEditEvent::SetValue{value,..}|SnapshotEditEvent::InsertValue{value,..}=>value,_=>return Err(invalid().into())};let mut fields=Vec::new();if wrapping.is_some(){fields.try_reserve_exact(2).map_err(|_|err("Part21 input carrier allocation failed"))?;}let value=std::mem::replace(input,DslValue::Null);self.input=Some(if let Some((kind,key))=wrapping{fields.push(("kind".into(),DslValue::String(kind.into())));fields.push((key.into(),value));let capacity=fields.capacity()*size_of::<(String,DslValue)>()+fields.iter().map(|(key,value)|key.capacity()+if let DslValue::String(text)=value{if key=="kind"{text.capacity()}else{0}}else{0}).sum::<usize>();progress.retained_capacity_bytes=capacity;DslValue::Object(fields)}else{value});self.phase=Phase::Source;}
 Phase::Source=>{let input=self.input.take().ok_or_else(invalid)?;let(source,receipt)=match Input::admit_owned(input,(),grant){Ok(value)=>value,Err((error,input,_))=>{self.input=Some(input);return Err(error.into());}};self.source=Some(source);progress=receipt;self.phase=Phase::Shell;}
 Phase::Shell=>{let(receiver,receipt)=Receiving::begin_shell(grant)?;self.receiving=Some(receiver);progress=receipt;self.phase=Phase::Capture;}
 Phase::Capture=>{progress=self.receiving.as_mut().unwrap().admit_original(&mut self.source,grant)?;self.phase=Phase::Birth;}
 Phase::Birth=>{progress=self.receiving.as_mut().unwrap().begin_receiver(grant)?;self.phase=Phase::Receive;}
 Phase::Receive=>{let step=cx.with_native_receiving(|control|self.receiving.as_mut().unwrap().advance(control,64,grant)).map_err(|error|semio_framework_job::OriginalTurnFailure::debit_original(error,cx))?;progress=step.progress();if matches!(step,RetainedCloneStep::Complete(_)){self.phase=Phase::Take;}}
 Phase::Take=>{let(value,receipt)=self.receiving.as_mut().unwrap().take(grant)?.ok_or_else(invalid)?;self.received=Some(value);progress=receipt;self.phase=Phase::Apply;}
 Phase::Apply=>{let mut path=self.path.unwrap();let value=target(instance,path)?;match path.target{
 Target::Whole|Target::Payload=>{let next=self.received.take().ok_or_else(invalid)?;self.old=Some(std::mem::replace(value,next));self.phase=Phase::Done;}
 Target::Items=>{if !matches!(self.received,Some(V::List(_))){return Err(invalid().into());}if !matches!(value,V::List(_)|V::Typed{..}){return Err(invalid().into());}let Some(V::List(next))=self.received.take()else{unreachable!()};let previous=std::mem::replace(items(value)?,next);self.old=Some(V::List(previous));self.phase=Phase::Done;}
 Target::Collection(position)=>{let values=items(value)?;let length=values.len();let position=if position==usize::MAX{if matches!(self.operation,Operation::Insert){length}else{length.saturating_sub(1)}}else{position};let admitted=match self.operation{Operation::Insert=>position<=length,Operation::Remove=>position<length,Operation::Move(from)=>from<length&&position<length,Operation::Set=>false};if !admitted{return Err(err("Part21 collection index is outside its domain").into());}path.target=Target::Collection(position);self.path=Some(path);self.length=match self.operation{Operation::Insert=>length.checked_add(1).ok_or_else(invalid)?,Operation::Remove=>length.checked_sub(1).ok_or_else(invalid)?,_=>length};self.collection=Some(std::mem::take(values));self.index=0;self.phase=Phase::Allocate;}}
 }
 Phase::Allocate=>{let mut values=Vec::new();values.try_reserve_exact(self.length).map_err(|_|err("Part21 collection capacity allocation failed"))?;progress.retained_capacity_bytes=values.capacity()*size_of::<V>();self.output=Some(values);self.phase=Phase::Rebuild;}
 Phase::Rebuild=>{let path=self.path.unwrap();let Target::Collection(position)=path.target else{return Err(invalid().into())};if self.index==self.length{let output=self.output.take().ok_or_else(invalid)?;*items(target(instance,path)?)?=output;self.phase=Phase::Done;}else{let next=match self.operation{Operation::Insert if self.index==position=>self.received.take().ok_or_else(invalid)?,operation=>{let index=match operation{Operation::Insert if self.index>position=>self.index-1,Operation::Remove if self.index>=position=>self.index+1,Operation::Move(from)if self.index==position=>from,Operation::Move(from)if from<position&&self.index>=from&&self.index<position=>self.index+1,Operation::Move(from)if from>position&&self.index>position&&self.index<=from=>self.index-1,_=>self.index};std::mem::replace(&mut self.collection.as_mut().unwrap()[index],V::Unset)}};self.output.as_mut().unwrap().push(next);self.index+=1;}}
 Phase::Done=>return Ok(true),
 }
 cx.consume_retained(progress)?;cx.consume_fuel(1);Ok(matches!(self.phase,Phase::Done))
 }
 pub(super)fn begin_close(&mut self){self.closing=true;if let Some(receiving)=self.receiving.as_mut(){receiving.begin_close();}}
 pub(super)fn terminal_is_empty(&self)->bool{self.input.is_none()&&self.source.is_none()&&self.receiving.is_none()&&self.received.is_none()&&self.old.is_none()&&self.collection.is_none()&&self.output.is_none()&&self.retirement.is_empty()}
 pub(super)fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(receiving)=self.receiving.as_ref(){return if receiving.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:2*size_of::<Option<Receiving>>(),depth:1,..Default::default()})}else{receiving.close_demands(body)};}if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<V>(false,&None,body);}if self.input.is_some(){return self.retirement.next_owner_demands::<DslValue>(true,&None,body);}if self.received.is_some()||self.old.is_some(){return self.retirement.next_owner_demands::<V>(true,&None,body);}if self.collection.is_some()||self.output.is_some(){return self.retirement.next_owner_demands::<Vec<V>>(true,&None,body);}if let Some(source)=self.source.as_ref(){return if source.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:2*size_of::<Option<Input>>(),depth:1,..Default::default()})}else{source.next_close_demand(body)};}Ok(Default::default())}
 pub(super)fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(invalid());}if !retained_clone_grant_admits(grant,self.close_demands(grant.maximum_copy_bytes)?){return Ok(RetainedCloneStep::Progress(Default::default()));}if let Some(receiving)=self.receiving.as_mut(){if !receiving.terminal_is_empty(){return receiving.close_step(grant);}self.receiving.take();return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:2*size_of::<Option<Receiving>>(),..Default::default()}));}if !self.retirement.is_empty(){return self.retirement.step_granted(grant);}if self.input.is_some(){return self.retirement.begin_granted(&mut self.input,grant)?.ok_or_else(invalid);}for value in [&mut self.received,&mut self.old]{if value.is_some(){return self.retirement.begin_granted(value,grant)?.ok_or_else(invalid);}}for values in [&mut self.collection,&mut self.output]{if values.is_some(){return self.retirement.begin_granted(values,grant)?.ok_or_else(invalid);}}if let Some(source)=self.source.as_mut(){if !source.terminal_is_empty(){return source.close_step(grant);}self.source.take();return Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:2*size_of::<Option<Input>>(),..Default::default()}));}Ok(RetainedCloneStep::Complete(Default::default()))}
}
